#!/usr/bin/env python3
"""Build ordinary HTML from the retained collection. No dependencies or network."""
from pathlib import Path
import argparse, json, re, shutil, html
from datetime import datetime

ROOT=Path(__file__).resolve().parents[1]
parser=argparse.ArgumentParser()
parser.add_argument('--archive',type=Path,default=ROOT/'collection')
args=parser.parse_args(); SRC=args.archive; OUT=ROOT/'site'
e=html.escape
for folder in ['assets','writing','downloads','recordings','transcripts']:(OUT/folder).mkdir(exist_ok=True,parents=True)
for name in ['steven-schrembeck.jpg','steven-schrembeck-family.jpg']:shutil.copy2(SRC/'memorial'/name,OUT/'assets'/name)
for folder in ['reality','collected']:shutil.copy2(SRC/folder/'cover.jpg',OUT/'assets'/f'{folder}-cover.jpg')
POSTS=json.loads((SRC/'cox-workplace/memorial/remembering-steven-schrembeck-data-2026-10-10.json').read_text())['posts']
ORIGINAL=(SRC/'memorial/READ.html').read_text()
body=ORIGINAL.split('<p>Man am I')[1].split('</article>')[0]
body='<p>Man am I'+body
body=body.replace('src="steven-schrembeck.jpg"','src="assets/steven-schrembeck.jpg"')
body=body.replace('src="steven-schrembeck-family.jpg"','src="assets/steven-schrembeck-family.jpg"')
body=re.sub(r'<h2>(.*?)</h2>',lambda m:f'<h2 id="section-{re.sub(r"[^a-z0-9]+","-",m[1].lower()).strip("-")}">{m[1]}</h2>',body)
# Preserve source wording, including its original chronology and attribution.
shutil.copy2(SRC/'memorial/READ.html',ROOT/'output/original-memorial.html')
(OUT/'downloads/memories.json').write_text(json.dumps([{k:p.get(k,'') for k in ['id','type','by','text','team','year','month','context']} for p in POSTS],ensure_ascii=False,indent=2))
GLASSES='<svg class="glasses" viewBox="0 0 64 34" fill="none" aria-hidden="true"><path d="M3 9h22l-2 16H8L3 9Zm36 0h22l-5 16H41L39 9ZM25 13c5-4 9-4 14 0M2 8 0 3m62 5 2-5" stroke="currentColor" stroke-width="3.5" stroke-linejoin="round"/></svg>'
NAV=[('story.html','His story'),('work.html','Words & work'),('memories.html','Memories'),('photos.html','Photographs')]

def page(name,title,content,active='',depth=0,description=None):
 base='../' if depth else ''
 nav=''.join(f'<a href="{base}{url}"'+(' aria-current="page"' if active==url else '')+f'>{label}</a>' for url,label in NAV)
 description=description or 'Remembering Steven Schrembeck through his words, his work, and the people whose lives he touched.'
 markup=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · Remembering Steven</title><meta name="description" content="{e(description)}"><meta name="theme-color" content="#f8f6ef"><meta name="robots" content="noindex,nofollow"><link rel="icon" href="{base}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}assets/style.css"><script src="{base}assets/app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><div class="wrap"><header class="site-header"><a class="brand" href="{base}index.html" aria-label="Remembering Steven, home">{GLASSES}<span>Remembering Steven</span></a><button class="menu-button" aria-expanded="false" aria-controls="site-navigation">Menu</button><nav class="site-nav" id="site-navigation" aria-label="Main navigation">{nav}<a class="nav-memory" href="{base}archive.html"{(' aria-current="page"' if active=='archive.html' else '')}>Keep a copy <span aria-hidden="true">↗</span></a></nav></header><main id="main">{content}</main><footer class="site-footer"><a class="brand" href="{base}index.html">{GLASSES}<span>For Steven. For all who knew him.</span></a><div class="footer-links"><a href="{base}timeline.html">A timeline</a><a href="{base}archive.html">About the collection</a></div><span>Local preview · October 2026</span></footer></div></body></html>'''
 (OUT/name).write_text(markup)

def head(kicker,title,intro=''):
 return f'<header class="page-head"><p class="eyebrow">{kicker}</p><h1>{title}</h1>'+ (f'<p class="intro">{intro}</p>' if intro else '')+'</header>'

def quote(text,author,context):
 return f'<article class="memory-teaser"><blockquote>“{e(text)}”</blockquote><cite>{e(author)}<span>{e(context)}</span></cite></article>'

page('index.html','A curious mind. A generous soul.',f'''
<section class="hero" aria-labelledby="hero-title"><div><p class="eyebrow">A life remembered, in words and moments</p><h1 id="hero-title"><span>Steven</span><span>Schrembeck.</span></h1><p class="hero-subtitle">A curious mind. A generous soul.<br>A friend who made room for others.</p><div class="hero-actions"><a class="button" href="story.html">Meet Steven <span aria-hidden="true">↗</span></a><a class="text-link" href="work.html">Explore his work <span aria-hidden="true">→</span></a></div><p class="hero-note">“nothing happens unless you make it happen”</p></div><figure class="hero-photo"><img src="assets/steven-schrembeck-family.jpg" alt="Steven with Amanda and their two sons, smiling together by the ocean" width="720" height="407" fetchpriority="high"><figcaption class="caption"><span>Steven, Amanda, and their boys.</span><span class="photo-label">The people at the heart of it all.</span></figcaption></figure></section>
<nav class="routes" aria-label="Ways to remember"><a class="route" href="story.html"><span class="route-num">01</span><span><span class="route-title">The person behind the glasses</span><span class="route-sub">A friend, a father, a different way of seeing.</span></span><span class="arrow" aria-hidden="true">↗</span></a><a class="route" href="work.html"><span class="route-num">02</span><span><span class="route-title">In his own words</span><span class="route-sub">Writing, stories, and a voice to return to.</span></span><span class="arrow" aria-hidden="true">↗</span></a><a class="route" href="memories.html"><span class="route-num">03</span><span><span class="route-title">What stays with us</span><span class="route-sub">Small moments. A lasting difference.</span></span><span class="arrow" aria-hidden="true">↗</span></a></nav>
<section class="section story-grid"><div><p class="eyebrow">The person behind the glasses</p><h2 style="margin-top:16px">A different way<br>of seeing.</h2><div class="portrait-label"><img src="assets/steven-schrembeck.jpg" alt="Steven in his green glasses" width="62" height="62" loading="lazy"><div>Engineer. Writer. Storyteller.<span>Husband, father, and friend.</span></div></div></div><div class="story-prose"><p>Steven brought a designer’s eye to his work and a restless curiosity to the world. He built interfaces, imagined other worlds, and followed questions wherever they led.</p><p>To the people around him, he was also the person who made time. The encouraging voice. The offer to help. The colleague whose colorful glasses could make you smile.</p><a class="text-link" href="story.html">More about Steven <span aria-hidden="true">→</span></a></div></section>
<section class="voice" aria-labelledby="voice-heading"><div><p class="eyebrow">A voice to come back to</p><h2 id="voice-heading">Spend a little time<br>with Steven.</h2><p>His questions, his imagination, his way of seeing. Hear the introduction to <em>Reality 101</em>, in his own voice.</p><a class="text-link" href="work.html#listen">Browse the recordings <span aria-hidden="true">→</span></a></div><div class="voice-player"><div class="recording"><img src="assets/reality-cover.jpg" alt="Reality 101 podcast artwork" width="72" height="72" loading="lazy"><div><small>REALITY 101 · INTRODUCTION</small><h3>Surprise, you can learn how it all works</h3><small>Steven Schrembeck · 1 min 49 sec</small></div></div><audio controls preload="none" aria-label="Reality 101 introduction"><source src="recordings/reality-101-introduction.mp3" type="audio/mpeg"></audio><p class="audio-note">A saved recording, here in the collection. <a href="transcripts/reality-101-introduction.html">Read transcript</a></p></div></section>
<section class="section"><div class="section-heading"><div><p class="eyebrow">The things we carry</p><h2>He made a difference.</h2></div><a class="text-link" href="memories.html">All memories <span aria-hidden="true">→</span></a></div><div class="memory-grid">{quote('He never not offered to help.','Mansi Demla','Remembering Steven')}{quote('If you say it matters, i’ll make it happen..','Steven, remembered by Winnie Widastra','On the icon styling · August 2023')}{quote('He consistently encouraged myself and other early career folks to explore and ask questions and always made himself available often offering a helping hand.','Vivian Milender','Remembering Steven')}</div></section>
<section class="preserve"><div><p class="eyebrow" style="margin-bottom:12px">Something to carry forward</p><h2>A place to return to. A copy to keep.</h2><p>For his boys, for his family, for the friends who knew him—and for those who will discover him through what he left.</p></div><a class="button secondary" href="archive.html">Keep a copy <span aria-hidden="true">↓</span></a></section>
''')

story_intro='One friend’s remembrance, part of a wider collection of memories.'
page('remembrance-jeff.html','A remembrance by Jeff Cameron',head('A shared remembrance','Remembering a friend.',story_intro)+f'''<div class="reading-layout"><aside class="reading-sidebar" aria-label="In this remembrance"><p class="eyebrow">In this remembrance</p><a href="#section-steven-s-work">His work</a><a href="#section-2021">2021–2026</a><a href="#section-what-he-left">What he left</a><a href="timeline.html">Explore the timeline →</a><a href="downloads/remembering-steven.pdf" download>Save the memories as PDF ↓</a></aside><article class="prose"><figure><img src="assets/steven-schrembeck-family.jpg" alt="Steven with Amanda and their sons by the ocean" width="720" height="407"><figcaption>Steven with his family.</figcaption></figure>{body}<div class="source-note">From Jeff Cameron’s <a href="https://remembering-steven-schrembeck.opzero.sh/">original remembrance</a>, first published September 30, 2026. Saved October 10, 2026. The wording is retained; the layout has been adapted for this collection.</div></article></div>''','story.html')

memory_cards=[]
for p in POSTS:
 kind='words' if p['type']=='words' else 'story'
 para=''.join('<p>'+e(t)+'</p>' for t in p['text'].split('\n\n'))
 text=f'<blockquote>{para}</blockquote>' if kind=='words' else f'<div class="memory-text">{para}</div>'
 context=f'<p class="context">{e(p.get("context",""))}</p>' if p.get('context') else ''
 memory_cards.append(f'<article class="memory-card" id="memory-{e(p["id"])}" data-entry data-kind="{kind}"><p class="memory-kind">'+('In Steven’s words' if kind=='words' else 'A memory')+f'</p>{text}{context}<div class="memory-author">'+('Remembered by ' if kind=='words' else '')+e(p['by'])+f'<span>{e(str(p.get("month", "")))} {e(str(p.get("year", "")))}</span></div></article>')
form='''<dialog id="memory-dialog" aria-labelledby="memory-title"><div class="dialog-top"><h2 id="memory-title">A memory worth keeping.</h2><button class="close-button" data-close-dialog aria-label="Close memory form">×</button></div><p class="small">A moment, a conversation, something that still makes you smile. Save it as a text file to keep or share with the person caring for this collection. Nothing is sent or published here.</p><form data-memory-form><label for="memory-name">Your name</label><input id="memory-name" name="name" autocomplete="name" required maxlength="120"><label for="memory-connection">How you knew Steven <span class="muted">(optional)</span></label><input id="memory-connection" name="connection" maxlength="200"><label for="memory-text">Your memory</label><textarea id="memory-text" name="memory" required maxlength="20000"></textarea><button class="button" type="submit">Download my memory <span aria-hidden="true">↓</span></button><p class="small" data-form-status role="status" style="margin-top:18px"></p></form></dialog>'''
page('memories.html','What stays with us',head('Shared by the people who knew him','What stays with us.','The encouragement. The humor. The green glasses. Memories of Steven, in the words of his friends and colleagues.')+'''<button class="button secondary js-only" data-open-dialog="memory-dialog">Write a memory <span aria-hidden="true">+</span></button><div class="searchbar js-only"><label class="visually-hidden" for="memory-search">Find a memory</label><input class="search-input" type="search" id="memory-search" placeholder="Search a name, a moment, a word…" data-search><div class="filter-buttons" aria-label="Filter memories"><button class="filter-button" data-filter="all" aria-pressed="true">All memories</button><button class="filter-button" data-filter="story" aria-pressed="false">Stories</button><button class="filter-button" data-filter="words" aria-pressed="false">Steven’s words</button></div></div><p class="results-status" data-results role="status">29 memories</p><noscript><p class="noscript-note">All memories are shown below. Your browser’s Find feature can search this page.</p></noscript><div class="memories-list">'''+''.join(memory_cards)+'''</div><div class="empty-state" data-empty hidden><h3>No memories found.</h3><p>Try a different word or name.</p><button class="button secondary" data-reset>Show all memories</button></div><p class="source-note">These 29 entries come from the supplied Cox memorial export, saved October 10, 2026. Names, wording, and contributor-assigned years are retained. Attachment screenshots and two comment replies remain in the full archive. Each contribution is one person’s recollection. The collection makes room for all of them.</p>'''+form,'memories.html')

articles=[]
for f in (SRC/'blog/pages').glob('*.txt'):
 if f.name.endswith('.headers.txt') or f.stem=='index':continue
 lines=f.read_text().splitlines()
 if 'Status' not in lines or 'Featured' not in lines:continue
 status=lines[lines.index('Status')+1]
 if status=='Unpublished':continue
 title=lines[0]; date=lines[lines.index('Created time')+1]; start=lines.index('Featured')+1
 while start<len(lines) and lines[start]=='Featured':start+=1
 desc=' '.join(lines[lines.index('Description')+1:lines.index('Featured')])
 content=[]
 for line in lines[start:]:
  if line.startswith(('✉','🔙','Copyright 2026')):break
  content.append(line)
 articles.append({'slug':f.stem,'title':title,'date':date,'description':desc,'lines':content,'sort':datetime.strptime(date,'%b %d, %Y %I:%M %p')})
 shutil.copy2(f,OUT/'downloads'/f.name)
articles.sort(key=lambda a:a['sort'],reverse=True)
for a in articles:
 mins=max(1,round(len(' '.join(a['lines']).split())/210))
 paragraphs=''.join(f'<p>{e(line)}</p>' for line in a['lines'] if line)
 page('writing/'+a['slug']+'.html',a['title'],f'''<header class="page-head article-head"><div class="breadcrumbs"><a href="../work.html">Words &amp; work</a><span>/</span><span>A Different Compass</span></div><h1>{e(a['title'])}</h1><p class="intro">{e(a['description'])}</p><div class="article-meta"><span>By Steven Schrembeck</span><span>{a['sort'].strftime('%B %-d, %Y')}</span><span>{mins} min read</span></div></header><article class="prose article-body {'poem' if a['slug']=='to-know' else ''}">{paragraphs}<div class="source-note">A text reading copy from <em>A Different Compass</em>. Wording is retained from the saved text export; formatting has been simplified and images are not included in this reading edition. Date above is the source’s “Created time.” <a href="../downloads/{a['slug']}.txt" download>Download the original text export</a>. Full captured pages remain in the preservation archive.</div><p class="bottom-link"><a href="../work.html#writing">← More from A Different Compass</a></p></article>''','work.html',1)

recordings=[('reality/003-trailer-surprise-you-can-learn-how-it-all-works.mp3','reality-101-introduction','Reality 101','Surprise, you can learn how it all works','1 min 49 sec','reality','Steven’s introduction to his journal of experiences and explorations.'),('collected/001-reverie.mp3','reverie','Collected','Reverie','17 min 25 sec','collected','An audio story from Steven’s collection of science fiction and fantasy.'),('collected/012-mortal-steel-trailer.mp3','mortal-steel-trailer','Collected','Mortal Steel · Trailer','1 min 28 sec','collected','A first step into the world of Mortal Steel, with music, voices, and sound design.')]
jobs=json.loads((SRC/'transcripts/associations.json').read_text())['jobs']
albums=[]
for source,slug,series,title,duration,cover,desc in recordings:
 shutil.copy2(SRC/source,OUT/'recordings'/f'{slug}.mp3')
 job=next(j for j in jobs if j['source_path']==source)
 transcript=(SRC/job['transcript_files']['txt']).read_text()
 shutil.copy2(SRC/job['transcript_files']['txt'],OUT/'transcripts'/f'{slug}.txt')
 shutil.copy2(SRC/job['transcript_files']['vtt'],OUT/'transcripts'/f'{slug}.vtt')
 page('transcripts/'+slug+'.html',title+' — transcript',head('Recording transcript',e(title),e(series)+' · '+duration)+f'''<div class="article-body"><audio controls preload="none" style="width:100%" aria-label="{e(title)}"><source src="../recordings/{slug}.mp3" type="audio/mpeg"></audio><div class="note-panel">Machine transcription (Scribe v2), created October 10, 2026. It has not been reviewed word for word and may contain errors. The saved recording is the primary source.</div><div class="prose">{''.join('<p>'+e(t)+'</p>' for t in transcript.splitlines() if t.strip())}</div><p class="bottom-link"><a href="../work.html#listen">← Back to recordings</a></p></div>''','work.html',1)
 albums.append(f'''<article class="album"><div class="album-header"><img src="assets/{cover}-cover.jpg" alt="{e(series)} artwork" loading="lazy" width="84" height="84"><div><p class="eyebrow">{series} · {duration}</p><h3 style="margin-top:8px">{e(title)}</h3></div></div><p>{desc}</p><audio controls preload="none" aria-label="{e(title)}"><source src="recordings/{slug}.mp3" type="audio/mpeg"></audio><a class="text-link" href="transcripts/{slug}.html">Read transcript</a><a class="text-link" href="recordings/{slug}.mp3" download>Save recording ↓</a></article>''')
rows=''.join(f'<a class="work-row" href="writing/{a["slug"]}.html"><div><small>{a["sort"].strftime("%B %Y")} · A Different Compass</small><h3>{e(a["title"])}</h3><p>{e(a["description"])}</p></div><span aria-hidden="true">↗</span></a>' for a in articles)
page('work.html','In his own words',head('Writing · audio fiction · explorations','In his own words.','Essays, imagined worlds, and questions worth following. A place to meet Steven through the things he made.')+f'''<nav class="library-tabs" aria-label="Work collections"><a href="#writing">The writing <span class="muted">17</span></a><a href="#listen">The recordings <span class="muted">3</span></a><a href="#more">More to explore</a></nav><section id="writing" class="section"><div class="section-heading"><div><p class="eyebrow">A Different Compass</p><h2>Follow his curiosity.</h2></div><p class="small muted">Saved words, ready to read.</p></div><div class="work-list">{rows}</div></section><section id="listen"><div class="section-heading"><div><p class="eyebrow">Listen, and linger</p><h2>His voice. His imagination.</h2></div></div><div class="album-grid">{''.join(albums)}</div><p class="source-note">These three recordings are included as actual files and play offline. Transcripts are machine generated and labeled as unreviewed. The complete preservation archive holds all 63 saved audio recordings and 24 videos.</p></section><section id="more" class="section"><div class="section-heading"><div><p class="eyebrow">The wider collection</p><h2>More of Steven’s world.</h2></div></div><div class="work-list"><a class="work-row" href="https://www.youtube.com/@seekingminima"><div><small>Video · original channel</small><h3>Seeking Minima</h3><p>Meaning in AI, our future, and being better humans. 22 videos are held in the family archive.</p></div><span aria-hidden="true">↗</span></a><a class="work-row" href="archive.html"><div><small>Preserved offline</small><h3>The complete collection</h3><p>Podcast episodes, interviews, workplace presentations, original pages, and source notes.</p></div><span aria-hidden="true">→</span></a></div></section>''','work.html')

page('photos.html','The moments we keep',head('Photographs','The moments we keep.','Two photographs from the original remembrance. A family together. Those unmistakable glasses.')+'''<div class="gallery"><figure><a class="photo-button" data-photo href="assets/steven-schrembeck-family.jpg" aria-label="Enlarge the family photograph"><img src="assets/steven-schrembeck-family.jpg" alt="Steven Schrembeck with Amanda and their two sons on a balcony by the ocean" width="720" height="407"></a><figcaption>Steven, Amanda, and their boys.<br><a href="assets/steven-schrembeck-family.jpg" download>Save photograph ↓</a></figcaption></figure><figure><a class="photo-button" data-photo href="assets/steven-schrembeck.jpg" aria-label="Enlarge Steven’s portrait"><img src="assets/steven-schrembeck.jpg" alt="Steven in his bright green glasses" width="260" height="227"></a><figcaption>Steven, and those unmistakable green glasses.<br><a href="assets/steven-schrembeck.jpg" download>Save photograph ↓</a></figcaption></figure></div><p class="source-note">Photographs retained at their saved resolution. Dates and photographer credits were not supplied; none have been inferred.</p><dialog class="photo-dialog" id="photo-dialog" aria-label="Photograph viewer"><div class="dialog-top"><span class="eyebrow">A moment to keep</span><button class="close-button" data-close-dialog aria-label="Close photograph">×</button></div><img alt=""><p data-photo-caption></p></dialog>''','photos.html')

timeline=[('2021','“okay, i can help”','Jeff asks a question about machine learning. Within the hour, Steven shares his own repositories and offers to introduce him to the team that could help.','msg me anytime if i can help test or be a practice audience. want to see you succeed!'),('2022','Becoming dad friends','Jeff invites Steven to his daughter’s birthday party. Steven asks whether both of his boys can come.',''),('2023','A way with people','Jeff remembers Steven’s advice on getting out of a meeting gracefully.','Telling people you trust them completely is the best way to get out of something but make them feel good'),('2024','Permission to keep learning','Advice on knowledge, ego, and the freedom of not needing to look smart.','Don\'t be impressed by knowledge. Anyone can acquire that. Take your ability to learn new things very seriously though'),('2025','The encouragement that stays','When Jeff tells Steven he has a new job, Steven writes back.','i\'m so proud of you man. nothing happens unless you make it happen. ...sometimes after way too long'),('2026','Pointing people toward good work','Steven encourages Jeff to share a generative UI experiment. Later, their last real conversation is about what in AI is worth paying attention to.','all i did was point them at what you\'d already done ;)')]
page('timeline.html','A friendship, in moments',head('2021–2026 · remembered by Jeff Cameron','A friendship,<br>in moments.','A few moments from Jeff’s remembrance. Small exchanges that reveal so much about Steven.')+'<div class="timeline">'+''.join(f'<section class="timeline-item"><div class="timeline-year">{year}</div><div><h2>{e(title)}</h2><p>{e(text)}</p>'+ (f'<blockquote>“{e(q)}”</blockquote>' if q else '')+'</div></section>' for year,title,text,q in timeline)+'</div><p class="source-note">This is a timeline of a friendship, drawn from Jeff’s original remembrance. It is not a complete biography. <a href="story.html">Read the full remembrance</a>.</p>','story.html')

page('archive.html','A copy to keep',head('Keeping his story close','A copy to keep.','This place is made to be read, saved, and carried forward. Ordinary files, a familiar voice, and words that can stay with you.')+'''<div class="download-grid"><article class="download-card"><p class="eyebrow">01 · The website</p><h2>Take this place with you.</h2><p>A complete offline copy of this website: the photographs, 17 reading copies, 29 memories, three recordings, transcripts, and the printable memory book. Unzip it and open START-HERE.html.</p><a class="button" href="downloads/remembering-steven-website.zip" download>Download the website <span aria-hidden="true">↓</span></a><p class="small" style="margin-top:16px;margin-bottom:0">About 20 MB · ZIP file · No account needed</p></article><article class="download-card"><p class="eyebrow">02 · The written memories</p><h2>Something to hold.</h2><p>A readable PDF of Jeff’s remembrance and the 29 collected memories. Keep it with the photographs, print it, or pass it on.</p><a class="button secondary" href="downloads/remembering-steven.pdf" download>Download the memory book <span aria-hidden="true">↓</span></a><p class="small" style="margin-top:16px;margin-bottom:0">PDF · Prepared October 10, 2026</p></article></div><section class="section"><p class="eyebrow">The complete preservation collection</p><h2 style="margin-top:16px">More than fits on a website.</h2><p class="care-note">The separate family archive holds approximately 4.8 GB: all 19 captured articles, 63 audio recordings, 24 videos, original metadata, workplace material, and source records. The website download above contains a selected reading and listening edition; it does not contain that entire archive.</p><div class="status-list"><div class="status-row"><span>Local preservation archive</span><span class="status">Collected</span></div><div class="status-row"><span>Website and printable memory book</span><span class="status">Ready to keep</span></div><div class="status-row"><span>GitHub Pages</span><span class="status pending">Not yet published</span></div><div class="status-row"><span><a href="https://jcameronjeff.github.io/steven-schrembeck-memorial/">GitHub Pages</a> &amp; <a href="https://github.com/jcameronjeff/steven-schrembeck-memorial">repository with Git LFS</a></span><span class="status">Independent copy</span></div><div class="status-row"><span>Internet Archive &amp; Wayback copies</span><span class="status pending">Not yet submitted</span></div><div class="status-row"><span>Perma.cc copies</span><span class="status pending">Not yet submitted</span></div><div class="status-row"><span>Copies held by two trusted people</span><span class="status pending">To arrange</span></div></div><p class="care-note">No provider can promise forever. Keeping complete copies with people who care is part of the plan. Publication and archive links will be added here once they exist and have been checked.</p></section><section class="preserve"><div><p class="eyebrow" style="margin-bottom:14px">For whoever cares for this next</p><h2>Simple instructions. All the pieces.</h2><p>The handover guide explains how to open, copy, check, and republish the collection. Keep it alongside the files.</p></div><a class="button secondary" href="downloads/CARETAKER-GUIDE.txt" download>Save the handover guide <span aria-hidden="true">↓</span></a></section><p class="source-note">Collection notes: two captured blog entries marked “Unpublished” are retained in the family archive and omitted from the 17 reading pages here. Five original blog images could not be retrieved. The three guest appearances listed as missing in the original inventory remain missing. Original materials and their source notes remain available in the complete collection. <a href="downloads/collection-notes.txt">Read the original collection notes</a>.</p>''','archive.html')
